/**
 * Logo de AWS: letras en [letters] y sonrisa en naranja de marca. Las letras
 * oficiales son azul oscuro, que no se ve sobre fondo oscuro: para esos casos
 * se usa una variante con las letras blancas (AwsLogoOnDark en AppIcons).
 */
internal fun buildAwsLogo(name: String, letters: Color): ImageVector =
    ImageVector.Builder(
        name = name,
        defaultWidth = 24.dp,
        defaultHeight = 24.dp,
        viewportWidth = 1000f,
        viewportHeight = 1000f
    )
        .addPath(
            pathData = addPathNodes(AwsLogoPaths.LETTERS),
            pathFillType = PathFillType.EvenOdd,
            fill = SolidColor(letters)
        )
        .addPath(
            pathData = addPathNodes(AwsLogoPaths.SMILE),
            pathFillType = PathFillType.EvenOdd,
            fill = SolidColor(AwsBrandOrange)
        )
        .build()
